# Make chapter number scale automatically as missions advance.
sub(r"function campaignReward\(id,next,xp,gold,drop\)\{.*?\}\nfunction campaignObjective",r'''function campaignReward(id,next,xp,gold,drop){const st=ensureCampaignMain();if(st.completed.includes(id))return;gainXP(xp);player.gold=Number(player.gold||0)+gold;if(drop)addItem(drop,1);st.completed.push(id);st.mission=next;const num=parseInt(String(next||'mq_01').split('_')[1]||'1',10);st.chapter=Math.max(1,Math.ceil(num/4));st.progress={};writeCampaignMain(st);save();updateHud();const item=drop?` • Drop: ${drop}`:'';toastMsg(`Missão concluída: +${xp} EXP • +${gold} Ouro${item}`);window.dispatchEvent(new CustomEvent('despertar:campaign-progress'))}
function campaignObjective''','campaign reward')

sub(r"function campaignObjective\(\)\{.*?\}\nfunction startEntreVeus",r'''function campaignObjective(){const st=readCampaignMain();if(!st||!st.unlocked)return'Fale com Raul Vilar para receber a próxima missão.';const pr=st.progress||{},cm=st.mission;if(cm==='mq_01')return world==='orla'?'Entregue a caixa de filtros para Saira Vento.':'Vá até a caravana marcada e viaje para Orla.';if(cm==='mq_02')return`Resgate os moradores da área alagada (${(pr.rescued||[]).length}/3).`;if(cm==='mq_03')return (pr.clues||[]).length<3?`Investigue as inconsistências da rua (${(pr.clues||[]).length}/3).`:'Fale com Inês Lume e compare as três evidências.';if(cm==='mq_04'){if(world!=='cistern')return'Entre na Cisterna e investigue o padrão.';if((pr.valves||[]).length<3)return`Interrompa as válvulas do padrão (${(pr.valves||[]).length}/3).`;return pr.bossDefeated?'Use o portal de retorno.':'Derrote o Síndico da Cisterna.'}if(cm==='mq_05'){if(world!=='road')return'Vá até a saída de Orla e siga para a Estrada das Lanternas.';return pr.metLio?'Leve os remédios com Lio até a primeira cancela.':'Fale com Lio na entrada da estrada.'}if(cm==='mq_06'){const a=(pr.lanterns||[]).length,k=(pr.roadKills||[]).length;return`Reative as lanternas (${a}/3) e elimine as Sombras de Pedágio (${k}/3).`}if(cm==='mq_07'){const n=(pr.manifests||[]).length;return n<3?`Recupere os manifestos adulterados (${n}/3).`:'Volte até Lio e compare os registros.'}if(cm==='mq_08')return pr.bossDefeated?'A passagem foi liberada.':'Enfrente O Cobrador na cancela final.';if(cm==='mq_09')return'Capítulo 2 concluído. Retorne a Orla. Nova missão: Livro de pagamento.';return'Continue a campanha principal.'}
function startEntreVeus''','chapter2 objectives')

# Chapter 2 helpers and NPC dialogue.
marker="function travelOrla(){world='orla';player.x=180;player.y=735;projectiles=[];goblins=[];save();updateHud();toastMsg('Orla — Distrito da Cisterna')}"
helpers=r'''function travelRoad(){const st=ensureCampaignMain();if(!['mq_05','mq_06','mq_07','mq_08','mq_09'].includes(st.mission)){toastMsg('A estrada ainda não faz parte da sua missão atual.');return}world='road';player.x=150;player.y=720;projectiles=[];if(st.mission==='mq_05'){const inv=ensureInventory();if(!inv['Caixa de Remédios'])addItem('Caixa de Remédios',1)}spawnRoadEncounter();save();updateHud();toastMsg('Estrada das Lanternas')}
function returnOrlaFromRoad(){world='orla';player.x=1390;player.y=205;projectiles=[];goblins=[];save();updateHud();toastMsg('Retorno a Orla')}
function spawnRoadEncounter(){const st=ensureCampaignMain(),pr=st.progress||{};goblins=[];if(st.mission==='mq_06'){const killed=pr.roadKills||[];const pts=[{id:201,x:720,y:405},{id:202,x:1040,y:620},{id:203,x:1360,y:385}];goblins=pts.filter(e=>!killed.includes(e.id)).map(e=>({...e,r:19,hp:42,maxHp:42,dead:false,state:'idle',cooldown:.55+Math.random()*.5,windup:0,attackX:0,attackY:0,roadEnemy:true,name:'Sombra de Pedágio'}))}else if(st.mission==='mq_08'&&!pr.bossDefeated){const hp=Math.max(1,Number(pr.bossHp||260));goblins=[{x:1515,y:470,r:31,hp,maxHp:260,dead:false,id:280,state:'idle',cooldown:.65,windup:0,attackX:0,attackY:0,roadBoss:true,boss:true,name:'O Cobrador'}]}}
function checkMQ06(){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_06')return;const lit=(pr.lanterns||[]).length,kills=(pr.roadKills||[]).length;if(lit>=3&&kills>=3){goblins=[];campaignReward('mq_06','mq_07',110,70,'Pavio de Vigília');toastMsg('Nova missão: A soma dos passageiros')}}
function talkLio(){const st=ensureCampaignMain(),pr=st.progress||{},cm=st.mission;if(cm==='mq_05'){setDialog(`<b>${player.name}</b><br><br>Você é o Lio? Vim acompanhar os remédios pela Estrada das Lanternas.<br><br><b>Lio — Mensageiro da estrada</b><br><br>Sou eu. Ainda bem que mandaram um Desperto. A estrada continua aberta, mas as cancelas começaram a cobrar nomes de pessoas que não aparecem em registro nenhum.`,[['Vamos seguir',()=>{pr.metLio=true;st.progress=pr;writeCampaignMain(st);closeDialog();save();updateHud();toastMsg('Lio seguirá até a primeira cancela.')}],['Quem é você?',()=>setDialog('<b>Lio</b><br><br>Eu faço entregas entre Orla e os povoados da estrada. Antes dos Portais eu era aprendiz de carteiro. Depois da Catástrofe, entregar uma carta ou um remédio virou trabalho de risco.<br><br>Conheço cada posto desta rota, e justamente por isso sei que esses nomes novos nas cancelas não deveriam estar aqui.',[['Voltar',()=>talkLio()],['Encerrar',closeDialog]])],['O que está acontecendo?',()=>setDialog('<b>Lio</b><br><br>As lanternas marcam o caminho seguro. Quando começaram a apagar, surgiram cobranças estranhas nos postos. Quem não entrega um nome fica preso na rota. O pior é que ninguém sabe quem são as pessoas cobradas.',[['Voltar',()=>talkLio()],['Encerrar',closeDialog]])],['Depois',closeDialog]]);return}if(cm==='mq_07'){if((pr.manifests||[]).length<3){setDialog(`<b>${player.name}</b><br><br>Lio, encontrei registros adulterados, mas ainda faltam documentos.<br><br><b>Lio</b><br><br>Então continue procurando. Precisamos de cópias de postos diferentes para provar que não é um erro isolado.`);return}setDialog(`<b>${player.name}</b><br><br>Lio, achei três registros. Pessoas estão sendo contabilizadas como se fossem carga.<br><br><b>Lio</b><br><br>Então é isso. Os pedágios estão lucrando com gente que oficialmente não existe. Leve uma cópia, eu fico com outra. A cancela final vai tentar impedir que esses documentos saiam daqui.`,[['Comparar e registrar manifestos',()=>{closeDialog();campaignReward('mq_07','mq_08',130,90,'Manifesto de Passageiros');spawnRoadEncounter();toastMsg('Nova missão: Passagem contestada')}],['Quem é você?',()=>setDialog('<b>Lio</b><br><br>Sou mensageiro. Hoje, pelo visto, também virei testemunha.',[['Voltar',()=>talkLio()],['Encerrar',closeDialog]])],['Depois',closeDialog]]);return}if(cm==='mq_08'){setDialog(`<b>${player.name}</b><br><br>A cancela final está bloqueada.<br><br><b>Lio</b><br><br>É O Cobrador. Ele transforma recibos em correntes e tenta fazer todo mundo aceitar a conta sem perguntar quem está pagando. Não deixe os manifestos chegarem às mãos dele.`,[['Vou enfrentar ele',closeDialog],['Depois',closeDialog]]);return}setDialog('<b>Lio</b><br><br>A estrada nunca foi tranquila, mas pelo menos agora sabemos onde começa a mentira.')}
function inspectRoadGate(){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_05')return;if(!pr.metLio){toastMsg('Fale com Lio antes de seguir.');return}setDialog(`<b>${player.name}</b><br><br>Chegamos à cancela. Tenho os remédios para o posto seguinte.<br><br><b>Lio</b><br><br>Olhe a lista presa na madeira. Eles estão cobrando passagem em nome de três pessoas que nunca constaram nos registros da rota. Isso começou depois que as lanternas apagaram.`,[['Entregar remédios e registrar a lista',()=>{removeItem('Caixa de Remédios',1);closeDialog();campaignReward('mq_05','mq_06',70,45,'Lista de Pedágio');spawnRoadEncounter();toastMsg('Nova missão: Três luzes acesas')}],['Depois',closeDialog]])}
function activateRoadLantern(id){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_06')return;pr.lanterns=pr.lanterns||[];if(pr.lanterns.includes(id)){toastMsg('Lanterna já acesa.');return}pr.lanterns.push(id);st.progress=pr;writeCampaignMain(st);save();toastMsg(`Lanterna reativada ${pr.lanterns.length}/3`);checkMQ06()}
function collectRoadManifest(id,name){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_07')return;pr.manifests=pr.manifests||[];if(pr.manifests.includes(id)){toastMsg('Documento já recolhido.');return}setDialog(`<b>${name}</b><br><br>O documento separa mercadorias e passageiros em colunas diferentes, mas alguns nomes foram transferidos para a coluna de carga.`,[['Guardar cópia',()=>{pr.manifests.push(id);st.progress=pr;writeCampaignMain(st);closeDialog();save();updateHud();toastMsg(`Manifesto ${pr.manifests.length}/3 recuperado`)}],['Depois',closeDialog]])}
'''
rep(marker,helpers+'\n'+marker,'chapter2 helpers')

