sub(r"function hitGoblin\(g,d\)\{.*?\}\nfunction basicAttack",r'''function hitGoblin(g,d){if(g.dead)return;g.hp-=d;if(g.hp<=0){g.hp=0;g.dead=true;g.state='dead';if(world==='camp'){gainXP(8);player.gold=Number(player.gold||0)+5;addItem('Fragmento de Goblin',1);toastMsg('Drop: +8 EXP • +5 Ouro • Fragmento de Goblin');save()}else if(world==='cistern'&&g.boss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossDefeated=true;pr.bossHp=0;st.progress=pr;writeCampaignMain(st);campaignReward('mq_04','mq_05',180,120,'Inscrição de Namar');toastMsg('BOSS derrotado • Drop: Inscrição de Namar • Capítulo 1 concluído')}else if(world==='road'&&g.roadBoss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossDefeated=true;pr.bossHp=0;st.progress=pr;writeCampaignMain(st);campaignReward('mq_08','mq_09',240,180,'Selo do Cobrador');goblins=[];toastMsg('O Cobrador derrotado • Capítulo 2 concluído')}else if(world==='road'&&g.roadEnemy){const st=ensureCampaignMain(),pr=st.progress||{};pr.roadKills=pr.roadKills||[];if(!pr.roadKills.includes(g.id))pr.roadKills.push(g.id);st.progress=pr;writeCampaignMain(st);gainXP(12);player.gold=Number(player.gold||0)+7;addItem('Fragmento de Lacre',1);save();toastMsg('Drop: +12 EXP • +7 Ouro • Fragmento de Lacre');checkMQ06()}}else if(world==='cistern'&&g.boss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossHp=g.hp;st.progress=pr;writeCampaignMain(st)}else if(world==='road'&&g.roadBoss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossHp=g.hp;st.progress=pr;writeCampaignMain(st)}updateHud()}
function basicAttack''','road combat drops')

sub(r"function hurtPlayer\(d\)\{.*?\}\nfunction updateGoblin",r'''function hurtPlayer(d){player.hp=Math.max(0,player.hp-d);dangerFlash.style.opacity=.28;setTimeout(()=>dangerFlash.style.opacity=0,110);if(player.hp<=0){player.hp=player.maxHp;const sp=world==='cistern'?{x:130,y:630}:world==='road'?{x:150,y:720}:{x:160,y:610};player.x=sp.x;player.y=sp.y;for(const g of goblins){if(!g.dead){g.state='idle';g.cooldown=.8;g.windup=0}}toastMsg('Você caiu e retornou ao ponto seguro.');save()}updateHud()}
function updateGoblin''','road respawn')

