# Target arrows now guide Chapter 2 too.
sub(r"function target\(\)\{.*?\}\nfunction arrowToTarget",r'''function target(){if(world==='camp'&&mission===S.GOBLINS){const alive=goblins.find(g=>!g.dead);return alive||camp.returnPortal}if(world==='city'){if(mission===S.GO_GUILD||mission===S.RETURN_GUILD)return city.guildDoor;if(mission===S.PORTAL)return city.portal;if(mission===S.DONE&&currentCampaignMission())return orlaDeparture}if(world==='guild'){if(mission===S.REGISTER||mission===S.REPORT)return guild.reception;if(mission===S.CAPTAIN||mission===S.CAPTAIN_AFTER)return guild.captain;if(mission===S.BOARD)return guild.board;if(mission===S.PORTAL)return guild.exit}if(world==='orla'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_01')return orla.saira;if(cm==='mq_02')return orla.residents.find(r=>!(pr.rescued||[]).includes(r.id))||orla.saira;if(cm==='mq_03')return orla.clues.find(q=>!(pr.clues||[]).includes(q.id))||orla.ines;if(cm==='mq_04')return orla.cisternDoor;if(['mq_05','mq_06','mq_07','mq_08','mq_09'].includes(cm))return roadDeparture}if(world==='cistern'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_04'){const v=cistern.valves.find(v=>!(pr.valves||[]).includes(v.id));if(v)return v;return goblins.find(g=>!g.dead)||cistern.exit}if(cm==='mq_05')return cistern.returnPortal}if(world==='road'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_05')return pr.metLio?road.firstGate:road.lio;if(cm==='mq_06'){const l=road.lanterns.find(x=>!(pr.lanterns||[]).includes(x.id));if(l)return l;return goblins.find(g=>!g.dead)||road.lio}if(cm==='mq_07')return road.manifests.find(m=>!(pr.manifests||[]).includes(m.id))||road.lio;if(cm==='mq_08')return goblins.find(g=>!g.dead)||road.finalGate;if(cm==='mq_09')return road.returnGate}return null}
function arrowToTarget''','chapter2 targets')

# Road drawing and route marker in Orla.
insert_draw=r'''function drawRoadDepartureMarker(){const cm=currentCampaignMission();if(!['mq_05','mq_06','mq_07','mq_08','mq_09'].includes(cm))return;ctx.fillStyle='#5b4630';ctx.fillRect(roadDeparture.x-45,roadDeparture.y-24,90,48);ctx.fillStyle='#c89f58';ctx.fillRect(roadDeparture.x+28,roadDeparture.y-62,8,44);label('ESTRADA DAS LANTERNAS',roadDeparture.x-95,roadDeparture.y-72,'#f2d79a',13)}
function drawRoad(){ctx.fillStyle='#292b2b';ctx.fillRect(0,0,road.w,road.h);ctx.fillStyle='#554a38';ctx.fillRect(80,420,1640,150);ctx.fillStyle='#3b372d';for(let x=200;x<1700;x+=230){ctx.fillRect(x,120,100,80);ctx.fillRect(x,665,110,70)}label('ESTRADA DAS LANTERNAS',650,85,'#e6cf96',20);label('Retorno a Orla',55,710,'#ddd');ctx.fillStyle='#6c5940';ctx.fillRect(road.firstGate.x-36,road.firstGate.y-65,72,130);label('1ª CANCELA',road.firstGate.x-45,road.firstGate.y-78,'#e8d6ad');ctx.fillStyle='#5c4938';ctx.fillRect(road.finalGate.x-52,road.finalGate.y-85,104,170);label('CANCELA FINAL',road.finalGate.x-55,road.finalGate.y-98,'#e8d6ad');const cm=currentCampaignMission(),pr=progressMain();npc(road.lio.x,road.lio.y,'Lio','#b7a27c',cm==='mq_05'||(cm==='mq_07'&&(pr.manifests||[]).length>=3));for(const l of road.lanterns){const lit=(pr.lanterns||[]).includes(l.id);ctx.fillStyle=lit?'#e7c868':'#564c3c';ctx.fillRect(l.x-8,l.y-44,16,52);ctx.beginPath();ctx.arc(l.x,l.y-48,lit?17:13,0,Math.PI*2);ctx.fill();if(cm==='mq_06')label(lit?'Acesa':'Lanterna',l.x-28,l.y-72,lit?'#ffe58d':'#aaa')}if(cm==='mq_07')for(const m of road.manifests)if(!(pr.manifests||[]).includes(m.id)){ctx.fillStyle='#d8c9a3';ctx.fillRect(m.x-15,m.y-11,30,22);label(m.name,m.x-55,m.y-22,'#f1dfb3')}for(const g of goblins){if(g.dead)continue;if(g.state==='windup'){ctx.fillStyle='#d33a';ctx.beginPath();ctx.arc(g.attackX,g.attackY,g.roadBoss?62:48,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ff6565';ctx.stroke()}ctx.fillStyle=g.roadBoss?'#8c6c4f':'#6f665b';ctx.beginPath();ctx.arc(g.x,g.y,g.r,0,Math.PI*2);ctx.fill();label(g.name||'Sombra de Pedágio',g.x-(g.roadBoss?42:48),g.y-g.r-12,g.roadBoss?'#f1d2a2':'#ddd0bd',g.roadBoss?15:12);ctx.fillStyle='#222';ctx.fillRect(g.x-35,g.y+g.r+9,70,6);ctx.fillStyle='#b84b4b';ctx.fillRect(g.x-35,g.y+g.r+9,70*g.hp/g.maxHp,6)}}
'''
s=s.replace('function drawCamp(){',insert_draw+'function drawCamp(){',1)

sub(r"function draw\(\)\{.*?\}\nfunction label",r'''function draw(){ctx.clearRect(0,0,W,H);if(!player)return;const map=mapForWorld();cam.x=Math.max(0,Math.min(map.w-W,player.x-W/2));cam.y=Math.max(0,Math.min(map.h-H,player.y-H/2));ctx.save();ctx.translate(-cam.x,-cam.y);if(world==='city')drawCity();else if(world==='guild')drawGuild();else if(world==='orla'){drawOrla();drawRoadDepartureMarker()}else if(world==='cistern')drawCistern();else if(world==='road')drawRoad();else drawCamp();drawPlayer();ctx.restore();arrowToTarget();drawAim();updateHint()}
function label''','road draw loop')

# Interaction hints.
sub(r"function currentInteract\(\)\{.*?\}\nfunction updateHint",r'''function currentInteract(){if(!player)return'';if(world==='city'){if(near(city.guildDoor,82))return'Entrar na Guilda';if(near({x:470,y:500},78))return'Davi Moura';if(near({x:1080,y:480},78))return'Breno Carvalho';if(near(city.portal,82)&&mission===S.PORTAL)return'Portal Rank F';const cs=readCampaignMain();if(cs&&cs.unlocked&&near(orlaDeparture,82))return'Viajar para Orla'}if(world==='guild'){if(near(guild.exit,82))return'Sair da Guilda';if(near(guild.reception,78))return'Elena Duarte';if(near(guild.captain,78))return'Raul Vilar';if(near({x:520,y:290},76))return'Caio Nunes';if(near({x:570,y:360},76))return'Mirela Santos';if(near(guild.board,78))return'Quadro de Missões'}if(world==='orla'){const cm=currentCampaignMission(),pr=progressMain();if(near(orla.returnGate,82))return'Voltar à Cidade Inicial';if(near(orla.saira,78))return'Saira Vento';if(near(orla.ines,78))return'Inês Lume';if(['mq_05','mq_06','mq_07','mq_08','mq_09'].includes(cm)&&near(roadDeparture,88))return'Seguir pela Estrada das Lanternas';if(cm==='mq_02'&&orla.residents.some(r=>!(pr.rescued||[]).includes(r.id)&&near(r,75)))return'Resgatar morador';if(cm==='mq_03'&&orla.clues.some(q=>!(pr.clues||[]).includes(q.id)&&near(q,75)))return'Investigar evidência';if(cm==='mq_04'&&near(orla.cisternDoor,90))return'Entrar na Cisterna'}if(world==='cistern'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_04'&&near(cistern.exit,82))return'Sair da Cisterna';if(cm==='mq_04'&&cistern.valves.some(v=>!(pr.valves||[]).includes(v.id)&&near(v,75)))return'Interromper válvula';if(cm==='mq_05'&&near(cistern.returnPortal,88))return'Retornar a Orla'}if(world==='road'){const cm=currentCampaignMission(),pr=progressMain();if(near(road.returnGate,82))return'Voltar para Orla';if(near(road.lio,78))return'Lio';if(cm==='mq_05'&&near(road.firstGate,78))return'Inspecionar a cancela';if(cm==='mq_06'&&road.lanterns.some(l=>!(pr.lanterns||[]).includes(l.id)&&near(l,75)))return'Reativar lanterna';if(cm==='mq_07'&&road.manifests.some(m=>!(pr.manifests||[]).includes(m.id)&&near(m,75)))return'Recolher manifesto'}if(world==='camp'&&goblins.filter(g=>g.dead).length>=5&&near(camp.returnPortal,82))return'Portal de retorno';return''}
function updateHint''','road hints')

# Direct click on Lio follows the same dialogue model as the Guild NPCs.
needle="if(world==='city'&&near({x:1080,y:480},90)&&clicked({x:1080,y:480},34)){talkBreno();return}basicAttack(wx-player.x,wy-player.y)"
replace="if(world==='city'&&near({x:1080,y:480},90)&&clicked({x:1080,y:480},34)){talkBreno();return}if(world==='road'&&near(road.lio,90)&&clicked(road.lio,36)){talkLio();return}basicAttack(wx-player.x,wy-player.y)"
rep(needle,replace,'Lio mouse interaction')

